using CCOS.Shared;

namespace CCOS.Data.Entities;

/// <summary>
/// A customer's club membership (CAR-28). MemberId is the same number as the CustomerId.
/// Rows are never deleted: leaving sets IsActive = false, and rejoining reuses the same row.
/// Status (Active, Expired, Inactive) is never stored. It's worked out from IsActive and
/// MemberExpiration with StatusOn, using the club's date (America/Chicago).
/// </summary>
public class Member
{
    /// <summary>Same value as Customer.CustomerId (not generated by the database).</summary>
    public int MemberId { get; set; }

    /// <summary>The last day their dues cover. Renewing overwrites it.</summary>
    public DateOnly MemberExpiration { get; set; }

    /// <summary>False only when an admin marks them as having left the club.</summary>
    public bool IsActive { get; set; } = true;

    /// <summary>The first day they became a member. Never changes, even after rejoining.</summary>
    public DateOnly JoinedDate { get; set; }

    /// <summary>When they were marked as having left. Cleared on rejoin.</summary>
    public DateOnly? DeactivatedDate { get; set; }

    /// <summary>
    /// Which admin marked them as having left. Not linked to a table yet: the Admins table
    /// comes in CAR-74, so this stays empty until then.
    /// </summary>
    public int? DeactivatedByAdminId { get; set; }

    public Customer Customer { get; set; } = null!;

    /// <summary>Their current officer title, if they hold one.</summary>
    public Officer? Officer { get; set; }

    /// <summary>Every officer title they've ever held, including the current one.</summary>
    public ICollection<OfficerHistory> OfficerHistory { get; set; } = new List<OfficerHistory>();

    /// <summary>
    /// The member's status on the given club date. Inactive is checked first, so someone who
    /// left shows as Inactive even if their dues date is still in the future.
    /// </summary>
    public MemberStatus StatusOn(DateOnly today) =>
        !IsActive ? MemberStatus.Inactive
        : MemberExpiration < today ? MemberStatus.Expired
        : MemberStatus.Active;
}
